from __future__ import annotations

import math
import re
import unicodedata
from collections import defaultdict, deque
from dataclasses import dataclass

from ..cad.model import CadDocument, CadEntity, CadInsert, CadLine, CadPoint, CadPolyline, CadText
from .common import fitting_type_from_label
from .external_predictions import external_semantic_hint
from .semantics import MepDiscipline, MepSemantic, classify_layer_role, classify_mep_entity

_DIAM = re.compile(r'(?:DN|DIA(?:M)?|Ø)\s*[-_ ]?\s*(\d{2,4})(?:\s*MM)?', re.IGNORECASE)
_MATERIALS = ('CPVC','PPR','PEX','PVC','COBRE','AÇO','ACO','PEAD','PBA')


def _plain(value: str) -> str:
    normalized = unicodedata.normalize('NFKD', value or '')
    return ''.join(ch for ch in normalized if not unicodedata.combining(ch)).upper().strip()


def _entity_points(entity: CadEntity) -> list[CadPoint]:
    if isinstance(entity, CadLine):
        return [entity.start, entity.end]
    if isinstance(entity, CadPolyline):
        return [entity.points[0], entity.points[-1]]
    if isinstance(entity, CadInsert):
        return [entity.position]
    return []


def _entity_midpoint(entity: CadEntity) -> CadPoint | None:
    if isinstance(entity, CadLine):
        return CadPoint(x=(entity.start.x+entity.end.x)/2,y=(entity.start.y+entity.end.y)/2,z=(entity.start.z+entity.end.z)/2)
    if isinstance(entity, CadPolyline):
        pts=entity.points; return pts[len(pts)//2]
    if isinstance(entity, CadInsert): return entity.position
    return None


def _dist(a: CadPoint,b: CadPoint)->float:
    return math.dist((a.x,a.y,a.z),(b.x,b.y,b.z))


def _cell(p: CadPoint, size: float) -> tuple[int,int,int]:
    return (round(p.x/size),round(p.y/size),round(p.z/size))


def _neighbors(key: tuple[int,int,int]):
    x,y,z=key
    for dx in (-1,0,1):
        for dy in (-1,0,1):
            for dz in (-1,0,1):
                yield x+dx,y+dy,z+dz


def _text_facts(text: str) -> tuple[float|None,str|None,set[str]]:
    up=_plain(text)
    m=_DIAM.search(text.replace('_',' ')); diameter=float(m.group(1)) if m and 10 <= float(m.group(1)) <= 2000 else None
    material=next((m for m in _MATERIALS if _plain(m) in up),None)
    systems=set()
    if any(t in up for t in ('AGUA FRIA','AF ',' AF','AF-','AF_')): systems.add('cold_water')
    if any(t in up for t in ('AGUA QUENTE','AQ ',' AQ','AQ-','AQ_')): systems.add('hot_water')
    if any(t in up for t in ('ESGOTO','ESG ','ESG-','ESG_','SANIT')): systems.add('sanitary')
    if any(t in up for t in ('PLUVIAL','AP ',' AP','AP-','AP_')): systems.add('rainwater')
    if any(t in up for t in ('INCENDIO','HIDRANTE','SPRINK','SPK','FIRE')): systems.add('fire_protection')
    return diameter,material,systems


@dataclass(frozen=True)
class MepEvidence:
    semantic: MepSemantic
    score: float
    reasons: tuple[str,...]
    diameter_mm: float | None = None
    diameter_source: str | None = None
    material: str | None = None
    nearby_text: str | None = None
    connected_component_count: int = 0
    network_seeded: bool = False

    @property
    def create(self) -> bool:
        threshold=.70 if self.semantic.target=='pipe' else .65
        return self.score >= threshold


class MepEvidenceEngine:
    def __init__(self, *, text_radius_m: float=.60, connect_tolerance_m: float=.03):
        self.text_radius_m=text_radius_m; self.connect_tolerance_m=connect_tolerance_m

    def assess(self, document:CadDocument, discipline:MepDiscipline)->dict[str,MepEvidence]:
        base={e.id:classify_mep_entity(e) for e in document.entities}
        base={eid:s for eid,s in base.items() if s and s.discipline==discipline and s.target in {'pipe','fitting','equipment'}}
        by_id={e.id:e for e in document.entities}
        texts=[e for e in document.entities if isinstance(e,CadText)]
        text_grid=defaultdict(list); text_cell=max(self.text_radius_m,0.05)
        for t in texts:text_grid[_cell(t.position,text_cell)].append(t)

        component_grid=defaultdict(list); conn_cell=max(self.connect_tolerance_m,0.005)
        for eid,semantic in base.items():
            entity=by_id[eid]
            if semantic.target in {'fitting','equipment'} and isinstance(entity,CadInsert):
                component_grid[_cell(entity.position,conn_cell)].append(entity)

        line_ids=[eid for eid,s in base.items() if s.target=='pipe' and isinstance(by_id[eid],(CadLine,CadPolyline))]
        endpoint_grid=defaultdict(list)
        for eid in line_ids:
            for pt in _entity_points(by_id[eid]): endpoint_grid[_cell(pt,conn_cell)].append(eid)

        direct_seed=set(); facts={}
        adjacency=defaultdict(set)
        for eid in line_ids:
            entity=by_id[eid]
            # Same-network adjacency only; isolated architecture-like clusters do not become seeded without evidence.
            for pt in _entity_points(entity):
                for nk in _neighbors(_cell(pt,conn_cell)):
                    for other in endpoint_grid.get(nk,[]):
                        if other==eid:continue
                        if any(_dist(pt,op)<=self.connect_tolerance_m for op in _entity_points(by_id[other])):
                            adjacency[eid].add(other)
            midpoint=_entity_midpoint(entity); near=[]
            if midpoint:
                for nk in _neighbors(_cell(midpoint,text_cell)):
                    for t in text_grid.get(nk,[]):
                        if _dist(midpoint,t.position)<=self.text_radius_m: near.append(t)
            # Also catch labels placed near an endpoint.
            for pt in _entity_points(entity):
                for nk in _neighbors(_cell(pt,text_cell)):
                    for t in text_grid.get(nk,[]):
                        if _dist(pt,t.position)<=self.text_radius_m and t not in near: near.append(t)
            diameter=material=None; systems=set(); joined=' | '.join(t.text for t in near)
            for t in near:
                d,m,ss=_text_facts(t.text); diameter=diameter or d; material=material or m; systems|=ss
            component_count=0
            for pt in _entity_points(entity):
                for nk in _neighbors(_cell(pt,conn_cell)):
                    for ins in component_grid.get(nk,[]):
                        if _dist(pt,ins.position)<=self.connect_tolerance_m:component_count+=1
            own_diam=None
            m=_DIAM.search(f'{entity.layer} {getattr(entity,"block_name","")}'.replace('_',' '))
            if m and 10 <= float(m.group(1)) <= 2000: own_diam=float(m.group(1))
            if diameter or material or base[eid].system in systems or component_count or own_diam:
                direct_seed.add(eid)
            facts[eid]=(diameter or own_diam,material,joined or None,systems,component_count)

        seeded=set(direct_seed)
        q=deque(direct_seed)
        while q:
            cur=q.popleft()
            for other in adjacency.get(cur,()):
                if other not in seeded:
                    seeded.add(other);q.append(other)

        # Detect local stair/tread-like line patterns: many short, parallel, similarly-sized
        # segments with regular spacing and no direct MEP corroboration. This is a negative
        # signal only; a DN label/fitting connection wins over the pattern penalty.
        repetitive=set()
        groups=defaultdict(list)
        for eid in line_ids:
            e=by_id[eid]
            if not isinstance(e,CadLine): continue
            dx=e.end.x-e.start.x;dy=e.end.y-e.start.y;length=math.hypot(dx,dy)
            if length<=0 or length>3.0: continue
            angle=(math.atan2(dy,dx)%math.pi); angle_bucket=round(angle/math.radians(5))
            ux,uy=dx/length,dy/length; mx=(e.start.x+e.end.x)/2;my=(e.start.y+e.end.y)/2
            along=mx*ux+my*uy; normal=-mx*uy+my*ux
            groups[(e.layer.upper(),angle_bucket,round(length/.10),round(along/3.0))].append((eid,normal))
        for vals in groups.values():
            if len(vals)<5: continue
            ordered=sorted(v for _,v in vals); gaps=[b-a for a,b in zip(ordered,ordered[1:]) if .05<=b-a<=.50]
            if len(gaps)<4: continue
            mean=sum(gaps)/len(gaps); variance=sum((g-mean)**2 for g in gaps)/len(gaps)
            if mean>0 and math.sqrt(variance)/mean<=.35:
                repetitive.update(eid for eid,_ in vals if eid not in direct_seed)

        out={}
        for eid,semantic in base.items():
            entity=by_id[eid]; role=classify_layer_role(entity.layer)
            if role in {'architecture','context','annotation'}:continue
            reasons=[]
            base_score={
                'observed_layer_tb':.72,'observed_layer_cx':.66,'sprinkler_layer':.66,
                'generic_fire_token':.40,'generic_hydraulic_token':.40,'cad_profile':.72,
            }.get(semantic.evidence,.35)
            score=base_score; reasons.append(semantic.evidence)
            diameter=material=nearby=None; diameter_source=None; component_count=0; network_seed=False
            if semantic.target=='pipe':
                diameter,material,nearby,systems,component_count=facts.get(eid,(None,None,None,set(),0)); diameter_source='nearby_text' if nearby and diameter is not None else ('explicit_token' if diameter is not None else None)
                if diameter is not None:score+=.30;reasons.append('diameter_evidence')
                if material is not None:score+=.08;reasons.append('material_text')
                if semantic.system in systems:score+=.08;reasons.append('system_text')
                if component_count:score+=.22;reasons.append('connected_mep_component')
                if eid in seeded and eid not in direct_seed:score+=.18;network_seed=True;reasons.append('seeded_mep_network')
                if eid in repetitive:score-=.45;reasons.append('repetitive_parallel_pattern')
            elif isinstance(entity,CadInsert):
                ft,_=fitting_type_from_label(f'{entity.layer} {entity.block_name}')
                label=_plain(entity.block_name)
                if semantic.target=='equipment' or ft!='other':score+=.28;reasons.append('recognized_block_semantics')
                label_for_diameter=f'{entity.layer} {entity.block_name}'.replace('_',' ')
                m=_DIAM.search(label_for_diameter) or re.search(r'(?:^|[_\- ])(\d{2,4})$',entity.block_name)
                if m and 10<=float(m.group(1))<=2000:
                    diameter=float(m.group(1));diameter_source='block_suffix' if re.search(r'(?:^|[_\- ])(\d{2,4})$',entity.block_name) else 'explicit_token';score+=.14;reasons.append('insert_diameter_evidence')
            hint=external_semantic_hint(entity)
            if hint and hint.target==semantic.target and (hint.system is None or hint.system==semantic.system):
                bonus=min(.12,.12*hint.confidence);score+=bonus;reasons.append(f'external_hint:{hint.source}')
            out[eid]=MepEvidence(semantic=semantic,score=max(0.0,min(score,1.0)),reasons=tuple(reasons),diameter_mm=diameter,diameter_source=diameter_source,material=material,nearby_text=nearby,connected_component_count=component_count,network_seeded=network_seed)
        return out
